    "FilePath": "file:///node_modules/@pragmatic-tech-ai/todl/dist/compiler-services/emit/manifest.d.ts",
    "Content": "import { Repository } from \"../model/model.js\";\nimport { type Scalar } from \"../model/graph.js\";\nimport { type LogicalManifest } from \"../../manifest/logical.js\";\n/** The manifest version a data graph is pinned to. */\nexport interface ManifestRef {\n    model: string;\n    version: string;\n}\n/** A flattened, self-contained instance node (SPEC-03 §graph). */\nexport interface DataNode {\n    id: string;\n    type: string;\n    class?: string;\n    namespace: string;\n    attrs: Record<string, Scalar>;\n}\n/** A relationship-only edge (`via` member name becomes `rel`). */\nexport interface DataEdge {\n    from: string;\n    rel: string;\n    to: string;\n}\n/** The sharded data-graph artifact. */\nexport interface DataGraph {\n    manifestRef: ManifestRef;\n    nodes: DataNode[];\n    edges: DataEdge[];\n}\nexport declare class ManifestEmitter {\n    private readonly repo;\n    private readonly model;\n    private readonly version;\n    /** Structural markers that live in `attrs` today; never user data (idea #5). */\n    private static readonly MARKERS;\n    constructor(repo: Repository, model: string, version: string);\n    /** Emit both artifacts together. */\n    emit(): {\n        manifest: LogicalManifest;\n        graph: DataGraph;\n    };\n    /** The replicated meta/ontology manifest. */\n    emitManifest(): LogicalManifest;\n    /** The sharded, flattened instance graph pinned to the manifest. */\n    emitDataGraph(): DataGraph;\n    private emitConcepts;\n    /**\n     * The aspect definitions, or `undefined` when the model declares none (so a model\n     * without aspects emits exactly the manifest it always did). An aspect's own invariants\n     * are listed here; the concept that introduces the aspect still folds them in too.\n     */\n    private emitAspects;\n    /**\n     * Every user primitive a concept or aspect field type reaches, with its `: base` (or null when it has none),\n     * following base chains; `undefined` when none is reached, so a model without user primitives emits the manifest\n     * it always did.\n     */\n    private emitPrimitives;\n    /** The aspects `owner` includes directly, in declaration order. */\n    private includedAspects;\n    private fieldDefs;\n    private relationshipDefs;\n    private emitClasses;\n    private emitTaxonomies;\n    /**\n     * Aspects `concept` carries that its parent does not. Aspects are not emitted as\n     * concepts, so their invariants ride on the concept introducing them — just as a\n     * supertype's invariants stay on the supertype, a consumer walking `extends`\n     * sees each aspect invariant exactly once.\n     */\n    private introducedAspects;\n    /** The annotations applied to `nodeId` (via Annotated edges → application nodes). */\n    private annotationsOf;\n    private emitNodes;\n    private emitEdges;\n    /** An instance-tier domain node: not a class/term definition, not a model container. */\n    private isDataNode;\n    /**\n     * Instance-wins flattening: the class's fixed values fill fields the leaf\n     * leaves unset, then the leaf's own values override. Structural markers are\n     * stripped so `attrs` is user-only.\n     */\n    private flattenedAttrs;\n    private static asString;\n}\n"
