    "Content": "import type { Repository } from \"../../model/model.js\";\nimport { MetadataSnapshot } from \"../../../domain/metadata-snapshot.js\";\n/**\n * The parse fixtures as repositories and as frozen manifest snapshots, engine-free: shared by the manifest agreement\n * check here and the engine agreement checks under src/engine-bridge (which add the engine on top).\n */\nexport declare class ManifestFixture {\n    private static readonly FixtureDirPath;\n    private static readonly Utf8;\n    private static readonly FixtureDir;\n    private static readonly Model;\n    private static readonly Version;\n    private static readonly FixtureExtension;\n    private static readonly OrderFixture;\n    private static readonly OrderToValidate;\n    private static readonly Sales;\n    /** order-fulfillment.todl uses concepts (Lane, SequenceFlow) its metamodel never declares. */\n    private static readonly OrderUnbindable;\n    /** The metamodel fixtures the instance fixtures import; loaded with every fixture so its types resolve. */\n    private static readonly PrimitivesFile;\n    private static readonly EnumsFile;\n    private static readonly ConceptsFile;\n    private static readonly Dependencies;\n    static FixtureNames(): string[];\n    static Repo(names: string[]): Repository;\n    /** Ids of the data nodes whose type the metamodel never declares, so they cannot bind. */\n    static Unbindable(repo: Repository): string[];\n    /** The unbindable node ids a fixture is known to have (sorted). */\n    static ExpectedUnbindable(name: string): readonly string[];\n    /** The repository emitted, reflected and frozen as a one-manifest snapshot, unbindable nodes left out. */\n    static Graph(repo: Repository): MetadataSnapshot;\n    private static Source;\n}\n"
