    "Content": "import { type AspectDecl, type ConceptDecl, type Declaration } from \"./ast.js\";\nimport type { Repository } from \"../model/model.js\";\nimport { type Diagnostic } from \"../diagnostics/diagnostic.js\";\n/** The outcome of classifying one concept's `:` list. */\nexport interface ClassifiedBases {\n    /** The single parent concept (first entry), or null. */\n    parent: string | null;\n    /** Included aspects, in written order. */\n    aspects: string[];\n}\n/**\n * Classifies the `:` base list of concepts and aspects (type model R1/R2). Built once\n * per load from every parsed declaration (qualified name -> kind) plus the nodes\n * already in the model; the base names must already be resolved to canonical ids.\n */\nexport declare class BaseListClassifier {\n    private readonly model;\n    private static readonly NotAspectAfterFirstMessage;\n    private static readonly MultipleParentsMessage;\n    private static readonly ConceptAfterAspectMessage;\n    private static readonly AspectIncludesNonAspectMessage;\n    private static readonly DuplicateBaseMessage;\n    private readonly kinds;\n    constructor(model: Repository, units: readonly {\n        ns: string;\n        decl: Declaration;\n    }[]);\n    /** Split a concept's base list into its parent and aspects, diagnosing misplaced concepts. */\n    ClassifyConcept(decl: ConceptDecl, diagnostics: Diagnostic[]): ClassifiedBases;\n    /** The aspects an aspect includes; a non-aspect entry is diagnosed and dropped. */\n    ClassifyAspect(decl: AspectDecl, diagnostics: Diagnostic[]): string[];\n    private KindOf;\n    /** True (after a warning) when `base` repeats an earlier entry of the same list. */\n    private static DiagnoseDuplicate;\n    private static Error;\n}\n"
