    "FilePath": "file:///node_modules/@pragmatic-tech-ai/todl/dist/compiler-services/predicate/ast.d.ts",
    "Content": "/**\n * The predicate / derivation expression AST (design spec §4). A small, total\n * language: traversal, set algebra, quantifiers, comprehensions — evaluated\n * over the graph by {@link ../evaluate}. The text parser for these expressions\n * comes later, with the main surface parser; this module is the shape the\n * evaluator consumes and that tests build directly.\n *\n * Node kinds and operators are enums (never string-literal discriminants).\n */\nimport type { NodeId } from \"../model/graph.js\";\nexport declare enum ExprKind {\n    This = 0,\n    Var = 1,\n    Name = 2,\n    None = 3,\n    Member = 4,\n    Comprehension = 5,\n    Quantifier = 6,\n    Binary = 7,\n    Unary = 8\n}\nexport declare enum BinaryOp {\n    And = 0,\n    Or = 1,\n    Implies = 2,\n    Eq = 3,\n    Neq = 4,\n    In = 5\n}\nexport declare enum UnaryOp {\n    Not = 0\n}\nexport declare enum QuantifierKind {\n    All = 0,\n    Any = 1\n}\nexport interface ThisExpr {\n    kind: ExprKind.This;\n}\nexport interface VarExpr {\n    kind: ExprKind.Var;\n    name: string;\n}\n/** A bare reference to a node by id — an enum member (`service`) or a record (`&x`). */\nexport interface NameExpr {\n    kind: ExprKind.Name;\n    id: NodeId;\n}\nexport interface NoneExpr {\n    kind: ExprKind.None;\n}\nexport interface MemberExpr {\n    kind: ExprKind.Member;\n    target: Expr;\n    member: string;\n}\nexport interface ComprehensionExpr {\n    kind: ExprKind.Comprehension;\n    variable: string;\n    concept: NodeId;\n    body: Expr;\n}\nexport interface QuantifierExpr {\n    kind: ExprKind.Quantifier;\n    quantifier: QuantifierKind;\n    variable: string;\n    concept: NodeId;\n    body: Expr;\n}\nexport interface BinaryExpr {\n    kind: ExprKind.Binary;\n    op: BinaryOp;\n    left: Expr;\n    right: Expr;\n}\nexport interface UnaryExpr {\n    kind: ExprKind.Unary;\n    op: UnaryOp;\n    operand: Expr;\n}\nexport type Expr = ThisExpr | VarExpr | NameExpr | NoneExpr | MemberExpr | ComprehensionExpr | QuantifierExpr | BinaryExpr | UnaryExpr;\nexport declare const THIS: ThisExpr;\nexport declare const NONE: NoneExpr;\nexport declare function variable(name: string): VarExpr;\nexport declare function name(id: NodeId): NameExpr;\nexport declare function member(target: Expr, name: string): MemberExpr;\nexport declare function comprehension(name: string, concept: NodeId, body: Expr): ComprehensionExpr;\nexport declare function all(name: string, concept: NodeId, body: Expr): QuantifierExpr;\nexport declare function any(name: string, concept: NodeId, body: Expr): QuantifierExpr;\nexport declare function and(left: Expr, right: Expr): BinaryExpr;\nexport declare function or(left: Expr, right: Expr): BinaryExpr;\nexport declare function implies(left: Expr, right: Expr): BinaryExpr;\nexport declare function eq(left: Expr, right: Expr): BinaryExpr;\nexport declare function neq(left: Expr, right: Expr): BinaryExpr;\nexport declare function isIn(left: Expr, right: Expr): BinaryExpr;\nexport declare function not(operand: Expr): UnaryExpr;\n"
