    "Content": "import { Repository } from \"../../compiler-services/model/model.js\";\nimport { type DataGraph } from \"../../compiler-services/emit/manifest.js\";\nimport { type LogicalManifest } from \"../../manifest/logical.js\";\nimport type { TodlDocument } from \"../../compiler-services/emit/json.js\";\nimport type { CompiledPackage } from \"../../publish/publish.js\";\nimport type { ResolvedPackage, PackageRef as DomainPackageRef, SeedGraph } from \"../../domain/domain.js\";\nexport declare class PackageManifestBridge {\n    static repositoryOf(doc: TodlDocument, dependencies?: readonly TodlDocument[]): Repository;\n    static toLogical(repo: Repository, model: string, version: string): LogicalManifest;\n    static toResolved(pkg: CompiledPackage): ResolvedPackage;\n    static toResolvedJson(pkg: CompiledPackage): ResolvedPackage;\n    static toResolvedJsonDocument(doc: TodlDocument, model: string, version: string, dependencies: DomainPackageRef[]): ResolvedPackage;\n    static toResolvedDocument(doc: TodlDocument, model: string, version: string, dependencies: DomainPackageRef[]): ResolvedPackage;\n    static seedOf(graph: DataGraph): SeedGraph;\n}\n"
