    "Content": "import type { IReadTransaction, IWriteTransaction } from '../kv/KeyValue.js';\nimport { type ICommitApplied } from './LogEntry.js';\n/**\n * The commit log: Log(commit) = a LogEntry (a batch with its catalog version and created ids, or a\n * schema change with the resulting catalog), commits gap-free from 1, and Meta(\"commit\") = the last\n * commit number (absent = 0). Written only by the Committer inside its Writes; readable from any\n * snapshot as an ordered, self-sufficient changefeed (ruling F4).\n */\nexport declare class CommitLog {\n    private static readonly CommitName;\n    private static readonly ErrCorrupt;\n    /** Above every tuple-encoded integer key (integer type codes end at 0x1C). */\n    private static readonly LogEnd;\n    static ReadLastCommit(txn: IReadTransaction): Promise<bigint>;\n    /** Appends an encoded LogEntry. The caller writes commits consecutively and then calls WriteLastCommit once. */\n    Append(txn: IWriteTransaction, commit: bigint, entry: Uint8Array): void;\n    WriteLastCommit(txn: IWriteTransaction, commit: bigint): void;\n    Read(txn: IReadTransaction, commit: bigint): Promise<ICommitApplied | undefined>;\n    /** Entries with Commit > after, in commit order. */\n    Scan(txn: IReadTransaction, after: bigint): AsyncIterable<ICommitApplied>;\n}\n"
